style.css:
@-moz-document domain("roblox.com") {
/* Replace this with your hosted Quick Love font */
@font-face {
    font-family: "Quick Love";
    src: url("YOUR_QUICKLOVE_FONT_URL.woff2") format("woff2");
    font-weight: normal;
    font-style: normal;
}

/* Force Quick Love everywhere */
html,
body,
*,
span,
div,
p,
a,
button,
input,
textarea,
label,
h1,
h2,
h3,
h4,
h5,
h6,
.roblox-font-caption-header,
.roblox-font-caption-body,
.roblox-font-header-1,
.roblox-font-header-2,
.roblox-font-header-3,
.roblox-font-body,
.text,
.text-label,
.game-name,
.game-card-name,
.profile-name,
.profile-display-name,
.navbar,
.rbx-navbar,
.btn-primary,
.btn-secondary {
    font-family: "Quick Love" !important;
    font-weight: normal !important;
}

/* Search bars */
input,
textarea {
    font-family: "Quick Love" !important;
}

/* Buttons */
button {
    font-family: "Quick Love" !important;
}

/* Chat */
.chat-message-text,
.chat-line,
.chat-message {
    font-family: "Quick Love" !important;
}
}
